-- ====================================================================
-- ACTUALIZACIÓN INTEGRAL DEL LIBRO DE CAJA EMPRENDE CHAMBALA (2024-2026)
-- Sincronización oficial de 33 meses, 72 préstamos, arqueos y saldos
-- ====================================================================
BEGIN;

-- Desactivar triggers temporales para carga masiva
ALTER TABLE operacion DISABLE TRIGGER trg_operacion_periodo_cerrado;
ALTER TABLE operacion_detalle DISABLE TRIGGER trg_detalle_periodo_cerrado;

-- Ajustar restricción de recibo único para permitir duplicados por reinicio de talonario entre periodos
DROP INDEX IF EXISTS ux_operacion_recibo;
CREATE UNIQUE INDEX IF NOT EXISTS ux_operacion_periodo_recibo ON operacion (caja_id, periodo_id, nro_recibo) WHERE nro_recibo IS NOT NULL AND estado = 'VIGENTE';

-- Limpiar transacciones, cierres y préstamos previos para recreación limpia
DELETE FROM distribucion_utilidad_detalle;
DELETE FROM distribucion_utilidad;
DELETE FROM operacion_detalle;
DELETE FROM operacion;
DELETE FROM arqueo_caja;
DELETE FROM cierre_periodo;
DELETE FROM cuota_prestamo;
DELETE FROM prestamo;
DELETE FROM periodo;

