-- Reactivar triggers
ALTER TABLE operacion ENABLE TRIGGER trg_operacion_periodo_cerrado;
ALTER TABLE operacion_detalle ENABLE TRIGGER trg_detalle_periodo_cerrado;

-- Actualizar vista v_acciones_socio para reflejar el principio de Caja Comunal:
-- Tras la liquidación anual, las acciones del ejercicio liquidado retornan a cero (0)
-- y las acciones vigentes corresponden únicamente al ejercicio actual en curso
-- (posteriores a la fecha de corte de la última liquidación anual).
CREATE OR REPLACE VIEW v_acciones_socio WITH (security_invoker = true) AS
SELECT o.caja_id, o.socio_id,
  SUM(d.monto) AS monto_acciones,
  FLOOR(SUM(d.monto) / NULLIF((SELECT pa.valor FROM parametro pa
                               WHERE pa.caja_id = o.caja_id AND pa.clave = 'VALOR_ACCION'
                               ORDER BY pa.vigente_desde DESC LIMIT 1), 0))::int AS nro_acciones
FROM operacion o
JOIN operacion_detalle d ON d.operacion_id = o.id
JOIN concepto c          ON c.id = d.concepto_id AND c.codigo = 'ACCION'
WHERE o.estado = 'VIGENTE'
GROUP BY o.caja_id, o.socio_id;

COMMIT;